module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);
// direct sum-of-products priority encoder with shared prefix ORs
wire o31_16 = |a_i[31:16];
wire o31_24 = |a_i[31:24];
wire o31_28 = |a_i[31:28];
wire o31_20 = |a_i[31:20];
wire o31_12 = |a_i[31:12];
wire o31_8  = |a_i[31:8];
wire o31_4  = |a_i[31:4];

wire idx4 = o31_16;
wire idx3 = o31_24 | (~o31_16 & |a_i[15:8]);
wire idx2 = o31_28 | (~o31_24 & |a_i[23:20]) | (~o31_16 & |a_i[15:12]) | (~o31_12 & |a_i[7:4]);
wire idx1 = (|a_i[31:30]) | (~o31_28 & |a_i[27:26]) | (~o31_24 & |a_i[23:22]) |
            (~o31_20 & |a_i[19:18]) | (~o31_16 & |a_i[15:14]) | (~o31_12 & |a_i[11:10]) |
            (~o31_8  & |a_i[7:6])   | (~o31_4  & |a_i[3:2]);
wire [31:0] pn;
assign pn[31] = 1'b0;
assign pn[30] = ~a_i[31];
assign pn[29] = ~|a_i[31:30];
assign pn[28] = ~|a_i[31:29];
assign pn[27] = ~o31_28;
assign pn[26] = ~|a_i[31:27];
assign pn[25] = ~|a_i[31:26];
assign pn[24] = ~|a_i[31:25];
assign pn[23] = ~o31_24;
assign pn[22] = ~|a_i[31:23];
assign pn[21] = ~|a_i[31:22];
assign pn[20] = ~|a_i[31:21];
assign pn[19] = ~o31_20;
assign pn[18] = ~|a_i[31:19];
assign pn[17] = ~|a_i[31:18];
assign pn[16] = ~|a_i[31:17];
assign pn[15] = ~o31_16;
assign pn[14] = ~|a_i[31:15];
assign pn[13] = ~|a_i[31:14];
assign pn[12] = ~|a_i[31:13];
assign pn[11] = ~o31_12;
assign pn[10] = ~|a_i[31:11];
assign pn[9]  = ~|a_i[31:10];
assign pn[8]  = ~|a_i[31:9];
assign pn[7]  = ~o31_8;
assign pn[6]  = ~|a_i[31:7];
assign pn[5]  = ~|a_i[31:6];
assign pn[4]  = ~|a_i[31:5];
assign pn[3]  = ~o31_4;
assign pn[2]  = ~|a_i[31:3];
assign pn[1]  = ~|a_i[31:2];
assign pn[0]  = ~|a_i[31:1];

wire idx0 = (a_i[31]) | (pn[30]&a_i[29]) | (pn[28]&a_i[27]) | (pn[26]&a_i[25]) |
            (pn[24]&a_i[23]) | (pn[22]&a_i[21]) | (pn[20]&a_i[19]) | (pn[18]&a_i[17]) |
            (pn[16]&a_i[15]) | (pn[14]&a_i[13]) | (pn[12]&a_i[11]) | (pn[10]&a_i[9]) |
            (pn[8]&a_i[7])   | (pn[6]&a_i[5])   | (pn[4]&a_i[3])   | (pn[2]&a_i[1]);

wire hit = ~pn[0] | a_i[0];
wire [5:0] chosen_0 = {hit, idx4, idx3, idx2, idx1, idx0};

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= chosen_0;
    end
end
endmodule

module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);
// nibble level
wire [7:0] nh, n1, n0;
assign nh[0] = |a_i[3:0];   assign n1[0] = |a_i[3:2];   assign n0[0] = a_i[3] | (a_i[1] & ~a_i[2]);
assign nh[1] = |a_i[7:4];   assign n1[1] = |a_i[7:6];   assign n0[1] = a_i[7] | (a_i[5] & ~a_i[6]);
assign nh[2] = |a_i[11:8];  assign n1[2] = |a_i[11:10]; assign n0[2] = a_i[11] | (a_i[9] & ~a_i[10]);
assign nh[3] = |a_i[15:12]; assign n1[3] = |a_i[15:14]; assign n0[3] = a_i[15] | (a_i[13] & ~a_i[14]);
assign nh[4] = |a_i[19:16]; assign n1[4] = |a_i[19:18]; assign n0[4] = a_i[19] | (a_i[17] & ~a_i[18]);
assign nh[5] = |a_i[23:20]; assign n1[5] = |a_i[23:22]; assign n0[5] = a_i[23] | (a_i[21] & ~a_i[22]);
assign nh[6] = |a_i[27:24]; assign n1[6] = |a_i[27:26]; assign n0[6] = a_i[27] | (a_i[25] & ~a_i[26]);
assign nh[7] = |a_i[31:28]; assign n1[7] = |a_i[31:30]; assign n0[7] = a_i[31] | (a_i[29] & ~a_i[30]);

// byte level
wire [3:0] bh, b2, b1, b0;
assign bh[0] = nh[1] | nh[0]; assign b2[0] = nh[1];
assign b1[0] = nh[1] ? n1[1] : n1[0];
assign b0[0] = nh[1] ? n0[1] : n0[0];
assign bh[1] = nh[3] | nh[2]; assign b2[1] = nh[3];
assign b1[1] = nh[3] ? n1[3] : n1[2];
assign b0[1] = nh[3] ? n0[3] : n0[2];
assign bh[2] = nh[5] | nh[4]; assign b2[2] = nh[5];
assign b1[2] = nh[5] ? n1[5] : n1[4];
assign b0[2] = nh[5] ? n0[5] : n0[4];
assign bh[3] = nh[7] | nh[6]; assign b2[3] = nh[7];
assign b1[3] = nh[7] ? n1[7] : n1[6];
assign b0[3] = nh[7] ? n0[7] : n0[6];

// half-word level
wire [1:0] hh, h3, h2, h1, h0;
assign hh[0] = bh[1] | bh[0]; assign h3[0] = bh[1];
assign h2[0] = bh[1] ? b2[1] : b2[0];
assign h1[0] = bh[1] ? b1[1] : b1[0];
assign h0[0] = bh[1] ? b0[1] : b0[0];
assign hh[1] = bh[3] | bh[2]; assign h3[1] = bh[3];
assign h2[1] = bh[3] ? b2[3] : b2[2];
assign h1[1] = bh[3] ? b1[3] : b1[2];
assign h0[1] = bh[3] ? b0[3] : b0[2];

// word level
wire hit = hh[1] | hh[0];
wire w4 = hh[1];
wire w3 = hh[1] ? h3[1] : h3[0];
wire w2 = hh[1] ? h2[1] : h2[0];
wire w1 = hh[1] ? h1[1] : h1[0];
wire w0 = hh[1] ? h0[1] : h0[0];

wire [5:0] chosen_0 = {hit, w4, w3, w2, w1, w0};

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= chosen_0;
    end
end
endmodule

